import { motion } from "framer-motion";
import { FaLinkedin, FaQuoteLeft } from "react-icons/fa";

const testimonials = [
  {
    name: "Sarwar Protik",
    title: "Software Developer & AI Enthusiast",
    linkedin: "https://www.linkedin.com/in/sarwar-protik-663271329/",
    text: "Arif is one of the most dedicated people I've worked with. His depth in cybersecurity combined with solid backend skills makes him stand out. Whether it's a Django project or a security challenge, he always delivers with precision.",
    avatar: "SP",
    color: "#6366f1",
  },
  {
    name: "Mahmudul Hasan",
    title: "CS Student & Developer",
    linkedin: "https://www.linkedin.com/in/mahmudul-hasan-770969396/",
    text: "Working alongside Arif has been a great experience. He has a strong grasp of both theoretical concepts and practical implementation. His problem-solving approach in penetration testing is genuinely impressive.",
    avatar: "MH",
    color: "#06b6d4",
  },
  {
    name: "Sakib",
    title: "Software Engineer",
    linkedin: "https://www.linkedin.com/in/sakib-71b491367/",
    text: "Arif is a fast learner with a passion for security research. He brings real energy to any project he works on. His knowledge of tools like Burp Suite and Metasploit goes well beyond what you'd expect at his level.",
    avatar: "SK",
    color: "#10b981",
  },
  {
    name: "Md. Fardin Hossain",
    title: "Tech Enthusiast",
    linkedin: "https://www.linkedin.com/in/fardinhosn/",
    text: "Arif consistently demonstrates a unique blend of security mindset and development skills. His work on Django applications and his understanding of cryptographic systems reflect a maturity that's rare among peers.",
    avatar: "FH",
    color: "#f59e0b",
  },
  {
    name: "Tanvir Hasan",
    title: "Developer & Collaborator",
    linkedin: null,
    text: "I've collaborated with Arif on several projects and he never disappoints. He's thorough, reliable, and always willing to go the extra mile. His understanding of both offensive security and backend systems is top-notch.",
    avatar: "TH",
    color: "#f43f5e",
  },
];

export default function Testimonials() {
  return (
    <section id="testimonials" className="py-24 bg-white/[0.02]">
      <div className="max-w-6xl mx-auto px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-16"
        >
          <p className="text-indigo-400 font-code text-sm mb-2">what_they_say()</p>
          <h2 className="text-3xl sm:text-4xl font-bold">Testimonials</h2>
          <div className="w-16 h-0.5 bg-gradient-to-r from-indigo-500 to-cyan-500 mx-auto mt-4" />
        </motion.div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">
          {testimonials.map((t, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1 }}
              whileHover={{ y: -4 }}
              className="glass rounded-xl p-6 flex flex-col hover:border-white/15 transition-all duration-300"
            >
              {/* Quote icon */}
              <FaQuoteLeft className="text-2xl mb-4" style={{ color: t.color + "60" }} />

              {/* Text */}
              <p className="text-gray-400 text-sm leading-relaxed flex-1 mb-6">
                "{t.text}"
              </p>

              {/* Author */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div
                    className="w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold text-white flex-shrink-0"
                    style={{ background: t.color + "30", border: `1px solid ${t.color}50` }}
                  >
                    {t.avatar}
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-white">{t.name}</p>
                    <p className="text-xs text-gray-500">{t.title}</p>
                  </div>
                </div>
                {t.linkedin && (
                  <a
                    href={t.linkedin}
                    target="_blank"
                    rel="noreferrer"
                    className="text-gray-600 hover:text-indigo-400 transition-colors text-lg"
                  >
                    <FaLinkedin />
                  </a>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
